/* SHA-256 against FIPS 180-4 vectors, fed whole and in uneven pieces. Run
 * once as is and once with ZIRAN_SHA256_PORTABLE=1: on a CPU with SHA-256
 * instructions that checks both the hardware and the portable rounds. With
 * an argument it prints the hash of that many generated bytes and the time. */
#include "zir_sha256.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static void
hex(const unsigned char digest[32], char out[65])
{
    for(int i = 0; i < 32; i++)
        snprintf(out + i * 2, 3, "%02x", digest[i]);
}

static int
check(const unsigned char *data, size_t size, size_t piece, const char *expected)
{
    Sha256 hash;
    unsigned char digest[32];
    char text[65];
    Sha256Begin(&hash);
    for(size_t at = 0; at < size; at += piece)
        Sha256Add(&hash, data + at, size - at < piece ? size - at : piece);
    Sha256End(&hash, digest);
    hex(digest, text);
    if(strcmp(text, expected) == 0)
        return 1;
    fprintf(stderr, "%zu bytes in pieces of %zu: %s, want %s\n", size, piece, text, expected);
    return 0;
}

int
main(int argc, char **argv)
{
    if(argc > 1) {
        size_t size = (size_t)strtoull(argv[1], NULL, 10);
        unsigned char *data = malloc(size ? size : 1);
        uint32_t seed = 12345;
        for(size_t i = 0; i < size; i++) {
            seed = seed * 1103515245u + 12345u;
            data[i] = (unsigned char)(seed >> 16);
        }
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        Sha256 hash;
        unsigned char digest[32];
        char text[65];
        Sha256Begin(&hash);
        Sha256Add(&hash, data, size);
        Sha256End(&hash, digest);
        clock_gettime(CLOCK_MONOTONIC, &end);
        hex(digest, text);
        printf("%s %.1f ms\n", text, (end.tv_sec - start.tv_sec) * 1e3 +
                                     (end.tv_nsec - start.tv_nsec) / 1e6);
        free(data);
        return 0;
    }
    static unsigned char million[1000000];
    memset(million, 'a', sizeof(million));
    const char *two_blocks = "abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq";
    const size_t pieces[] = {1, 3, 55, 56, 63, 64, 65, 127, 128, 1000, 1000000};
    int ok = 1;
    for(size_t p = 0; p < sizeof(pieces) / sizeof(pieces[0]); p++) {
        size_t piece = pieces[p];
        ok &= check((const unsigned char *)"", 0, piece,
                    "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
        ok &= check((const unsigned char *)"abc", 3, piece,
                    "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
        ok &= check((const unsigned char *)two_blocks, strlen(two_blocks), piece,
                    "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1");
        ok &= check(million, sizeof(million), piece,
                    "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0");
    }
    if(!ok)
        return 1;
    printf("sha256: FIPS 180-4 vectors pass\n");
    return 0;
}
